from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a grid can be covered exactly by a subset of the tiles.

    Each tile can be rotated, must align with cells, and may be used at most
    once. Tiles may remain unused. Grid dimensions are at most 10 and there
    are at most 7 tiles.
    """
    # Discard tiles that cannot fit in either orientation. Canonical dimensions
    # also let the search avoid equivalent choices of identical tiles.
    shapes = []
    for a, b in tiles[:n]:
        a, b = sorted((a, b))
        if (a <= h and b <= w) or (b <= h and a <= w):
            shapes.append((a, b))
    shapes.sort(key=lambda shape: shape[0] * shape[1], reverse=True)
    count = len(shapes)
    areas = [a * b for a, b in shapes]
    orientations = []
    for a, b in shapes:
        choices = []
        for height, width in sorted({(a, b), (b, a)}):
            if height <= h and width <= w:
                mask = sum(((1 << width) - 1) << (row * w)
                           for row in range(height))
                choices.append((height, width, mask))
        orientations.append(choices)

    # Bit k records whether some subset of the remaining tiles has area k.
    subset_areas = [1] * (1 << count)
    for remaining in range(1, 1 << count):
        bit = remaining & -remaining
        index = bit.bit_length() - 1
        smaller = subset_areas[remaining ^ bit]
        subset_areas[remaining] = smaller | (smaller << areas[index])

    full = (1 << (h * w)) - 1

    @lru_cache(None)
    def search(covered: int, remaining: int) -> bool:
        if covered == full:
            return True
        empty_area = h * w - covered.bit_count()
        if not ((subset_areas[remaining] >> empty_area) & 1):
            return False

        # The first uncovered cell must be the upper-left cell of the tile
        # covering it: extending above or left would overlap an earlier cell.
        empty = full ^ covered
        position = (empty & -empty).bit_length() - 1
        row, column = divmod(position, w)
        tried = set()
        for index, shape in enumerate(shapes):
            bit = 1 << index
            if not (remaining & bit) or shape in tried:
                continue
            tried.add(shape)
            for height, width, base_mask in orientations[index]:
                if row + height > h or column + width > w:
                    continue
                placement = base_mask << position
                if not (covered & placement):
                    if search(covered | placement, remaining ^ bit):
                        return True
        return False

    return search(0, (1 << count) - 1)

