def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can become t with at most k single-character edits.

    Allowed edits are insertion, deletion, and replacement. Strings may have
    up to 500000 characters, and the specified edit budget is at most 20.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t:
        return True
    if k <= 0:
        return False
    if max(n, m) <= k:
        return True

    # On diagonal d = i - j, retain the furthest source position reachable
    # after each edit budget, extending every state through matching letters.
    i = 0
    while i < n and i < m and s[i] == t[i]:
        i += 1
    frontier = {0: i}
    for _ in range(k):
        candidates = {}
        for diagonal, i in frontier.items():
            j = i - diagonal
            if i < n:  # Delete s[i].
                d = diagonal + 1
                candidates[d] = max(candidates.get(d, -1), i + 1)
            if j < m:  # Insert t[j].
                d = diagonal - 1
                candidates[d] = max(candidates.get(d, -1), i)
            if i < n and j < m:  # Replace s[i] with t[j].
                candidates[diagonal] = max(
                    candidates.get(diagonal, -1), i + 1
                )

        frontier = {}
        for diagonal, i in candidates.items():
            j = i - diagonal
            while i < n and j < m and s[i] == t[j]:
                i += 1
                j += 1
            if i == n and j == m:
                return True
            frontier[diagonal] = i
    return False

