def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in [num1, num2] whose digit sum is in [min_sum, max_sum].

    Return the count modulo 10**9 + 7. Bounds are numeric strings with
    1 <= num1 <= num2 <= 10**22, and 1 <= min_sum <= max_sum <= 400.

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    modulus = 10**9 + 7

    def count_at_most(bound: str) -> int:
        # Each state records the digit sum and whether the prefix still
        # equals the bound. Leading zeroes represent shorter integers.
        limit_sum = min(max_sum, 9 * len(bound))
        if min_sum > limit_sum:
            return 0
        states = {(0, True): 1}
        for char in bound:
            bound_digit = int(char)
            next_states = {}
            for (digit_sum, tight), count in states.items():
                limit = bound_digit if tight else 9
                for digit in range(min(limit, limit_sum - digit_sum) + 1):
                    key = (digit_sum + digit, tight and digit == bound_digit)
                    next_states[key] = (next_states.get(key, 0) + count) % modulus
            states = next_states
        return sum(count for (digit_sum, _), count in states.items()
                   if min_sum <= digit_sum <= max_sum) % modulus

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_at_most(num2) - count_at_most(num1) + lower_is_good) % modulus

